public boolean hasDoubleLetter(String word) {
    for (int i = 0; i < word.length() - 1; i++) {
        if (word.charAt(i) == word.charAt(i + 1)) {
            return true;
        }
    }
    return false;
}

public int largestDigit(int num) {
    int max = 0;
    while (num > 0) {
        int digit = num % 10;
        if (digit > max) {
            max = digit;
        }
        num /= 10;
    }
    return max;
}

public double approxPi(int terms) {
    double sum = 0.0;
    for (int i = 0; i < terms; i++) {
        double term = 1.0 / (2 * i + 1);
        if (i % 2 == 0) {
            sum += term;
        } else {
            sum -= term;
        }
    }
    return sum * 4.0;
}

public boolean checkPrime(int num) {
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) {
            return false;
        }
    }
    return true;
}

public int countChar(String phrase, String letter) {
    phrase = phrase.toLowerCase();
    letter = letter.toLowerCase();
    int count = 0;
    for (int i = 0; i < phrase.length(); i++) {
        if (phrase.substring(i, i + 1).equals(letter)) {
            count++;
        }
    }
    return count;
}

public String diagonalPrint(int n) {
    String result = "";
    for (int row = 0; row < n; row++) {
        for (int col = 0; col < n; col++) {
            if (row == col) {
                result += "O ";
            } else {
                result += "* ";
            }
        }
        if (row < n - 1) {
            result += "\n";
        }
    }
    return result;
}

public String exclamation(String input) {
    String result = "";
    for (int i = 0; i < input.length(); i++) {
        result += input.substring(i, i + 1) + "!";
    }
    return result;
}

public int doubleNum(int input) {
    int doubleNum = 0;
    while (input < 100 && input > -100) {
        input *= 2;
        doubleNum++;
    }
    return doubleNum;
}

public String triPrint(int n) {
    String result = "";
    for (int i = n; i >= 1; i--) {
        for (int j = i; j >= 1; j--) {
            result += j + " ";
        }
        if (i > 1) {
            result += "\n";
        }
    }
    return result;
}
